PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?label ?dboDate ?dbpDate (STR(COALESCE(?dboDate, ?dbpDate)) AS ?rawDate)
WHERE {
  VALUES ?person { dbr:Joseph_Dudley dbr:Francisco_Herrera_Luque }
  OPTIONAL { ?person dbo:deathDate ?dboDate }
  OPTIONAL { ?person dbp:deathDate ?dbpDate }
  OPTIONAL { ?person rdfs:label ?label FILTER(lang(?label) = "en") }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earlier ?earlierLabel ?earlierDate WHERE {
  VALUES (?p1 ?p2) { (dbr:Joseph_Dudley dbr:Francisco_Herrera_Luque) }

  OPTIONAL { ?p1 dbo:deathDate ?d1dbo }
  OPTIONAL { ?p1 dbp:deathDate ?d1dbp }
  OPTIONAL { ?p2 dbo:deathDate ?d2dbo }
  OPTIONAL { ?p2 dbp:deathDate ?d2dbp }

  BIND( STR(COALESCE(?d1dbo, ?d1dbp)) AS ?s1 )
  BIND( STR(COALESCE(?d2dbo, ?d2dbp)) AS ?s2 )

  {
    FILTER(?s1 < ?s2)
    BIND(?p1 AS ?earlier)
    BIND(?s1 AS ?earlierDate)
  }
  UNION
  {
    FILTER(?s2 < ?s1)
    BIND(?p2 AS ?earlier)
    BIND(?s2 AS ?earlierDate)
  }

  OPTIONAL { ?earlier rdfs:label ?earlierLabel FILTER(lang(?earlierLabel) = "en") }
}

